#include <ruby.h>
#include <ruby/debug.h>
#include <valgrind/callgrind.h>

static int active, selected, depth, collecting, exclude_gc;
static unsigned long segments, entries;

static void gc_event(rb_event_flag_t event, VALUE data, VALUE self, ID mid, VALUE klass) {
    if (active && collecting && exclude_gc) CALLGRIND_TOGGLE_COLLECT;
    if (active && event == RUBY_INTERNAL_EVENT_GC_ENTER) segments++;
}

static VALUE select_category(VALUE self, VALUE mask) {
    selected = NUM2INT(mask);
    depth = 0;
    return Qnil;
}

static VALUE enter(VALUE self, VALUE mask) {
    if (!active || !(selected & NUM2INT(mask))) return Qfalse;
    entries++;
    if (depth++ == 0) {
        collecting = 1;
        CALLGRIND_TOGGLE_COLLECT;
    }
    return Qtrue;
}

static VALUE leave(VALUE self, VALUE entered) {
    if (!RTEST(entered)) return Qnil;
    if (--depth == 0) {
        CALLGRIND_TOGGLE_COLLECT;
        collecting = 0;
    }
    return Qnil;
}

static VALUE start(int argc, VALUE *argv, VALUE self) {
    VALUE exclude = Qfalse;
    rb_scan_args(argc, argv, "01", &exclude);
    exclude_gc = RTEST(exclude);
    segments = entries = 0;
    depth = 0;
    collecting = selected == 0;
    active = 1;
    CALLGRIND_START_INSTRUMENTATION;
    CALLGRIND_ZERO_STATS;
    if (!collecting) CALLGRIND_TOGGLE_COLLECT;
    return Qnil;
}

static VALUE finish(VALUE self) {
    if (depth) rb_raise(rb_eRuntimeError, "unbalanced category boundaries");
    active = 0;
    if (!collecting) CALLGRIND_TOGGLE_COLLECT;
    CALLGRIND_DUMP_STATS;
    CALLGRIND_STOP_INSTRUMENTATION;
    return ULONG2NUM(segments);
}

static VALUE entry_count(VALUE self) { return ULONG2NUM(entries); }

void Init_calibration_gate(void) {
    VALUE module = rb_define_module("LowrailCallgrindBench");
    rb_define_singleton_method(module, "select_category", select_category, 1);
    rb_define_singleton_method(module, "enter", enter, 1);
    rb_define_singleton_method(module, "leave", leave, 1);
    rb_define_singleton_method(module, "entries", entry_count, 0);
    rb_define_singleton_method(module, "start", start, -1);
    rb_define_singleton_method(module, "finish", finish, 0);
    rb_add_event_hook(gc_event, RUBY_INTERNAL_EVENT_GC_ENTER | RUBY_INTERNAL_EVENT_GC_EXIT, Qnil);
}
